#!/usr/bin/env python3
"""One-time materializer for the PSPMAN public tracker support files."""

from __future__ import annotations

import base64
import gzip
import hashlib
import json
from pathlib import Path

EXPECTED_SHA256 = "fdb72df1f31cea7ac8114746bc3d4dd0529ea39d4e621192d6d3c0a85d82310f"
PAYLOAD = """"""

root = Path(__file__).resolve().parents[1]
raw = gzip.decompress(base64.b64decode(PAYLOAD))
actual = hashlib.sha256(raw).hexdigest()
if actual != EXPECTED_SHA256:
    raise SystemExit(f"bundle checksum mismatch: {actual}")

bundle = json.loads(raw.decode("utf-8"))
for relative, content in bundle.items():
    target = root / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8", newline="\n")
    print(f"materialized {relative}")
